import Modal from 'flarum/common/components/Modal';
export default class ImagePreviewModal extends Modal {
  className() {
    return 'AdSlotImagePreviewModal Modal--large';
  }
  title() {
    return this.attrs.title || '图片预览';
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "AdSlotImagePreviewModal-body"
    }, m("img", {
      src: this.attrs.src,
      alt: this.attrs.alt || this.attrs.title || 'preview'
    })));
  }
}
flarum.reg.add('doingfb-adslot', 'admin/components/ImagePreviewModal', ImagePreviewModal);