import app from 'flarum/admin/app';
import ExtensionPanel from './components/ExtensionPanel';
import RenewalsPage from './components/RenewalsPage';
import ReviewsPage from './components/ReviewsPage';
const ADMIN_STYLE_OVERRIDE_ID = 'doingfb-adslot-admin-style-overrides';
function ensureAdminStyleOverrides() {
  if (typeof document === 'undefined' || document.getElementById(ADMIN_STYLE_OVERRIDE_ID)) {
    return;
  }
  const style = document.createElement('style');
  style.id = ADMIN_STYLE_OVERRIDE_ID;
  style.textContent = "\n    .AdSlotAdminTable--compact { min-width: 1080px; }\n    .AdSlotAdminTable-colMerchant { width: 17%; min-width: 200px; }\n    .AdSlotAdminTable-colThumb { width: 58px; min-width: 58px; }\n    .AdSlotAdminTable-colLink { width: 27%; min-width: 300px; max-width: 340px; }\n    .AdSlotAdminTable-colSettlement { width: 11%; min-width: 126px; }\n    .AdSlotAdminTable-colState { width: 8%; min-width: 92px; }\n    .AdSlotAdminTable-colTime { width: 7%; min-width: 88px; }\n    .AdSlotAdminTable-colTimeRange { width: 7%; min-width: 88px; }\n    .AdSlotAdminTable-colActions,\n    .AdSlotAdminTable th:last-child,\n    .AdSlotAdminTable td:last-child { width: 112px; min-width: 112px; }\n    .AdSlotAdminTable thead th { padding: 9px 7px; }\n    .AdSlotAdminTable tbody td { padding: 7px 6px; }\n    .AdSlotAdminTable-actions { gap: 3px; max-width: 112px; }\n    .AdSlotAdminAction--icon { width: 20px; min-width: 20px; height: 20px; }\n    .AdSlotBadge { min-width: 0; padding: 3px 8px; }\n    .AdSlotAdminTable-chip { min-height: 18px; padding: 0 5px; font-size: 10px; }\n    .AdSlotAdminTable-pill { gap: 4px; min-height: 22px; padding: 2px 5px; }\n    .AdSlotAdminTable-pill--stacked { align-items: center; gap: 2px; padding: 1px 5px; }\n    .AdSlotAdminTable-pillLabel,\n    .AdSlotAdminTable-pillValue { font-size: 10px; }\n    .AdSlotAdminTable-statGrid { flex-direction: row; flex-wrap: nowrap; align-items: center; gap: 2px; white-space: nowrap; }\n    .AdSlotAdminTable-stateGrid { flex-wrap: nowrap; gap: 2px; white-space: nowrap; }\n    .AdSlotAdminTable-timeRange { line-height: 1.15; }\n    .AdSlotAdminTable-inlineCluster { display: flex; align-items: center; gap: 6px; min-width: 0; width: 100%; }\n    .AdSlotAdminTable-inlineCluster--merchant,\n    .AdSlotAdminTable-inlineCluster--link { flex-wrap: nowrap; justify-content: flex-start; }\n    .AdSlotAdminTable-inlineCluster > * { min-width: 0; }\n    .AdSlotAdminTable-chipRow { flex-wrap: nowrap; gap: 5px; align-items: center; }\n    .AdSlotAdminTable-thumb,\n    .AdSlotAdminTable-thumbPlaceholder { width: 40px; height: 40px; }\n  ";
  document.head.appendChild(style);
}
app.initializers.add('doingfb-adslot', () => {
  ensureAdminStyleOverrides();
  app.routes.adslotRenewals = {
    path: '/adslot/renewals',
    component: RenewalsPage
  };
  app.routes.adslotReviews = {
    path: '/adslot/reviews',
    component: ReviewsPage
  };
  const extension = app.registry.for('doingfb-adslot');
  extension.registerSetting({
    setting: 'doingfb-adslot.baseMonthlyFee',
    type: 'number',
    label: 'Monthly advertising price (points)',
    help: 'Default monthly price used when a new advertisement is submitted.'
  }).registerSetting({
    setting: 'doingfb-adslot.noticeBarEnabled',
    type: 'boolean',
    label: 'Show provider page notice'
  }).registerPermission({
    icon: 'fas fa-rectangle-ad',
    label: app.translator.trans('doingfb-adslot.admin.permissions.review_ads'),
    permission: 'doingfb-adslot.reviewAds'
  }, 'moderate').registerPermission({
    icon: 'fas fa-bullhorn',
    label: app.translator.trans('doingfb-adslot.admin.permissions.manage_ads'),
    permission: 'doingfb-adslot.manageAds'
  }, 'moderate').registerPage(ExtensionPanel);
});